from lib import *
S = SS('j249')
steps = [
    step("同一批任务(4 个,各 500 ms,线程池 2 个线程)用四种方式收尾,JDK 21:shutdown() 调用 0 ms 就返回,之后 4 个任务都完成;shutdown() + awaitTermination 返回用时 900 ms,4 个完成;shutdownNow() 返回用时 6 ms,返回 2 个未开始的任务,2 个正在运行的被中断,0 个完成;close() 返回用时 909 ms,4 个完成。close() 等价于 shutdown() 加等待终止——它是阻塞的,不是“立即关闭”。", t=tl(S(1)), done=lidx(S(1), 'shutdown()                    调用返回用时', 'shutdown() + awaitTermination'), mark=lidx(S(1), 'shutdownNow()', 'close()'), b=bars([['shutdown()', 0, '0 ms'], ['shutdown()+awaitTermination', 900, '900 ms'], ['shutdownNow()', 6, '6 ms'], ['close()', 909, '909 ms']], 909, done=[0, 1, 2, 3]), kv=KV([['shutdown()', '不等待,任务继续跑完'], ['shutdownNow()', '中断运行中的,返回未开始的 2 个'], ['close()', '等待到全部完成(909 ms)']], ['close()'])),
    step("close() 等待期间调用线程被中断:150 ms 时中断了正在 close() 的线程,close() 在 159 ms 后返回,调用线程的中断标志仍是 true(被恢复);池里正在运行的 2 个任务被中断,没开始的 2 个被丢弃,0 个完成。close() 遇到中断会改成 shutdownNow(),而且把中断标志还给调用者。", t=tl(S(2)), done=lidx(S(2), '150 ms 时中断了正在 close() 的线程'), mark=lidx(S(2), '调用线程中断标志 = true', '被中断 2 个'), kv=KV([['中断正在 close() 的线程', '159 ms 后返回,中断标志 = true'], ['池里的任务', '2 个被中断,2 个未开始被丢弃,0 个完成']], ['池里的任务'])),
    step("ForkJoinPool.commonPool().close() 什么也不做:用时 0 ms,返回时任务(sleep 500 ms)没有完成,isShutdown() = false,之后还能提交并执行任务。CompletableFuture.runAsync(默认用 commonPool)之后 commonPool().close() 同样 0 ms、任务未完成。自建的 ForkJoinPool.close() 才会等待:用时 441 ms,返回时任务已完成,isTerminated() = true。try-with-resources 一个 commonPool 并不会等任务。", t=tl(S(3)), done=lidx(S(3), 'commonPool().close() 用时 0 ms'), mark=lidx(S(3), '自建 ForkJoinPool.close()', 'CompletableFuture.runAsync'), kv=KV([['commonPool().close()', '0 ms,任务未完成,池仍可用'], ['自建 ForkJoinPool.close()', '441 ms,任务完成,isTerminated']], ['commonPool().close()'])),
    step("ScheduledThreadPoolExecutor:默认策略是 getExecuteExistingDelayedTasksAfterShutdownPolicy() = true、getContinueExistingPeriodicTasksAfterShutdownPolicy() = false。350 ms 时 close():用时 1147 ms——它等到了延迟 1500 ms 的一次性任务,延迟任务已执行;周期任务(每 100 ms)在 close 前执行 4 次、close 后共 4 次(被取消)。把周期任务的继续策略设为 true 再 shutdown():600 ms 后周期任务共执行 8 次、isTerminated() = false——周期任务不停,池永远不会终止。", t=tl(S(4)), done=lidx(S(4), '默认策略'), mark=lidx(S(4), '350 ms 时 close()', 'setContinueExistingPeriodicTasksAfterShutdownPolicy(true)'), kv=KV([['close()(默认策略)', '等延迟任务 1147 ms,周期任务被取消'], ['继续策略 = true + shutdown()', '周期任务继续,isTerminated() = false']], ['继续策略 = true + shutdown()'])),
    step("任务不响应中断:任务忙等 1500 ms 不检查中断。shutdownNow() 立即返回(0 ms),未开始任务 0 个,此时任务未结束、isTerminated() = false;awaitTermination(300 ms) = false(距 shutdownNow 约 302 ms);再 awaitTermination(5 s) = true,距 shutdownNow 共约 1399 ms,任务此时才结束。shutdownNow() 只是发出中断,不等于任务停止。另外 JDK 17 上同样的 try-with-resources 无法编译(javac 报 try-with-resources not applicable to variable type),JDK 21 编译运行输出 ok。", t=tl(S(5)), done=lidx(S(5), 'shutdownNow() 立即返回'), mark=lidx(S(5), 'awaitTermination(300 ms) = false', '继续 awaitTermination(5 s) = true', 'JDK 17 javac 退出码', 'JDK 21 javac 退出码'), b=bars([['shutdownNow() 返回', 0, '0 ms'], ['任务真正结束', 1399, '约 1399 ms']], 1400, done=[0, 1]), kv=KV([['shutdownNow()', '立即返回,忙等任务仍在跑'], ['任务结束', '距 shutdownNow 约 1399 ms'], ['JDK 17', 'try-with-resources 编译失败']], ['shutdownNow()'])),
]
A = mkartj('j249', 249, 'Java,并发,ExecutorService,close,shutdown,线程池,真实验证,动画演示',
    '在 JDK 21 上实测 ExecutorService.close():它等价于 shutdown + 等待终止(909 ms),被中断时改为 shutdownNow;ForkJoinPool.commonPool().close() 什么也不等;ScheduledThreadPoolExecutor.close() 会等延迟任务(1147 ms)、取消周期任务;shutdownNow() 对不响应中断的任务没有效果;JDK 17 无法编译。',
    'JDK 19 起 ExecutorService 实现了 AutoCloseable,try-with-resources 看上去让线程池关闭变得简单。这篇逐一量出 close() 到底做了什么:什么时候阻塞、被中断时怎么办、对 commonPool 和定时线程池有什么特殊行为,以及 shutdownNow() 的边界。',
    [('909 ms', 'close() 等待 4 个各 500 ms、2 个线程的任务全部完成的用时(shutdown() 是 0 ms)'), ('0 ms', 'ForkJoinPool.commonPool().close() 的用时:不等待、不关闭'), ('1147 ms', 'ScheduledThreadPoolExecutor.close() 在 350 ms 时调用,等延迟 1500 ms 的任务的用时')],
    [('四种收尾方式', None), ('close() 遇到中断', None), ('commonPool', None), ('定时线程池', None), ('不响应中断的任务', None)],
    steps, [ENV_J + '。JDK 21.0.12 与 JDK 17.0.20(只用于编译对照);所有任务是自写的 sleep / 忙等任务', '没有验证:ThreadPerTaskExecutor(虚拟线程)的 close() 行为、close() 与 StructuredTaskScope 的关系、JDK 19 / 20 的行为、ThreadPoolExecutor 子类重写 terminated() 的时机'], 'ExecutorService 关闭')
